//import WebSite from "../runtime/WebSite.js";
import Util from "../lib/util.js";
import {Tonyu} from "tonyu2-runtime";
import FS from "./FS_global.js";
var Assets={};
Assets.resolve=function (url, prj, options) {
  options=options||{};
  var baseDir=FS.SFile.is(prj)?prj:prj.getDir();
  if (url==null) url="";
  /*url=url.replace(/\$\{([a-zA-Z0-9_]+)(\/)?\}/g, function (t,name,slash) {
      let val=WebSite[name];
      if (!val) val="(UNDEF_"+name+")";
      if (slash && !val.match(/\/$/)) val+="/";
      return val;
  });*/
  //if (WebSite.urlAliases[url]) url=WebSite.urlAliases[url];
  if (Util.startsWith(url,"ls:")||
  url.startsWith("./")) {
      var rel=Util.startsWith(url,"ls:")?
      url.substring("ls:".length):url;
      if (!baseDir) throw new Error("Basedir not specified");
      var f=baseDir.rel(rel);
      if (!f.exists()) throw new Error("Resource file not found: "+f);
      /*if (
          (WebSite.mp3Disabled && rel.match(/\.(mp3)$/)) ||
          (WebSite.mp4Disabled && rel.match(/\.(mp4|m4a)$/))
      ) {
          var oggf=baseDir.rel(rel.replace(/\.(mp3|mp4|m4a)$/,".ogg"));
          if (oggf.exists()) {
              f=oggf;
          }
      }*/
      if (options.asFile) return f;
      url=f.dataURL();
  }
  return url;
};
Tonyu.Assets=Assets;
export default Assets;
